// Колода событий акта 1: формат карточки, первая пачка — 40 карточек (задача И28) и вторая — 103 карточки, № 41–143 (задача И32). Замысел — docs/design/koloda.md.
// Здесь только данные: движка событий ещё нет. Карточка — одна завязка со слотами; генератор подставит людей, место и время,
// а натура того, кто решает, двинет выбор. id — будущие ключи сохранений: не менять.
import type { PoleKey, Want, Hold, Channel, ThreadId, HolderRole, LinkGroup } from "./types";
import type { Force } from "./forces";
import type { Clarity } from "./threads";
import { u, naNiti, shkala, SCALE_FORCE, type Cond, type Usl } from "./conditions";

// ---------- словари колоды ----------
// Уровень — кто решает и кто видит (koncept-3.md, раздел 10).
export type CardLevel = "lichnoe" | "dolzhnostnoe" | "peresechenie" | "stol";
export const CARD_LEVELS: Record<CardLevel, string> = { lichnoe: "личное", dolzhnostnoe: "должностное", peresechenie: "пересечение", stol: "стол Сенешаля" };
// Вид: событие, эпизод дела (какого — поле delo), предание или весть; во второй пачке — ход силы и опора (sily.md, 6.3 и раздел 9).
export type CardKind = "sobytie" | "epizod" | "predanie" | "vest" | "khod" | "opora";
export const CARD_KINDS: Record<CardKind, string> = {
  sobytie: "событие", epizod: "эпизод дела", predanie: "предание", vest: "весть", khod: "ход силы", opora: "опора",
};
// Дела Сенешаля (koncept-3.md, раздел 12, каталог).
export type DealId =
  | "doma_v_zamke" | "knigi_i_schyot" | "sud_i_skhod" | "arkhiv_i_predaniya" | "obezd_derevni" | "kromka" | "osmotr_rabot" | "mezha_i_pokosy"
  | "v_stavku" | "k_sosedyam" | "k_lesnym" | "v_vadelu" | "smotr_po_ledokhodu" | "osenniy_torg" | "vyezdnoy_sud";
export const DEALS: { id: DealId; name: string }[] = [
  { id: "doma_v_zamke", name: "Дома в замке" }, { id: "knigi_i_schyot", name: "Книги и счёт" }, { id: "sud_i_skhod", name: "Суд и сход" },
  { id: "arkhiv_i_predaniya", name: "Архив и предания" }, { id: "obezd_derevni", name: "Объезд деревни" }, { id: "kromka", name: "Кромка" },
  { id: "osmotr_rabot", name: "Осмотр работ" }, { id: "mezha_i_pokosy", name: "Межа и покосы" }, { id: "v_stavku", name: "В ставку" },
  { id: "k_sosedyam", name: "К соседям" }, { id: "k_lesnym", name: "К лесным" }, { id: "v_vadelu", name: "В Ваделу" },
  { id: "smotr_po_ledokhodu", name: "Смотр по ледоходу" }, { id: "osenniy_torg", name: "Осенний торг" }, { id: "vyezdnoy_sud", name: "Выездной суд" },
];
// Места владения первого акта (koncept-3.md, 3.1).
export type DeckPlace =
  | "zamok" | "nizhnyaya" | "verkhnyaya" | "pashnya" | "pokosy" | "vypas" | "melnitsa" | "perevoz" | "korchma" | "borti" | "delyanka" | "kromka" | "chasovnya" | "shakhta";
export const DECK_PLACES: { id: DeckPlace; name: string }[] = [
  { id: "zamok", name: "замок" }, { id: "nizhnyaya", name: "нижняя деревня у брода" }, { id: "verkhnyaya", name: "верхняя деревня у опушки" },
  { id: "pashnya", name: "пашня" }, { id: "pokosy", name: "покосы" }, { id: "vypas", name: "выпас" }, { id: "melnitsa", name: "мельница у залома" },
  { id: "perevoz", name: "перевоз" }, { id: "korchma", name: "корчма" }, { id: "borti", name: "борти" }, { id: "delyanka", name: "делянка" },
  { id: "kromka", name: "кромка" }, { id: "chasovnya", name: "часовня" }, { id: "shakhta", name: "старая шахта" },
];
// Где: место владения; «деревня» — любая из двух; «любое» — где угодно. За пределами владения — поле outside.
export type CardWhere = DeckPlace | "derevnya" | "lyuboe";
export const WHERE_ANY: Record<"derevnya" | "lyuboe", string> = { derevnya: "деревня — любая из двух", lyuboe: "любое место" };
export type Outside = "stavka" | "sosed" | "doroga";
export const OUTSIDE: Record<Outside, string> = { stavka: "ставка", sosed: "сосед", doroga: "дорога" };
// Когда: по дорожке года (koncept-3.md, 5.1) или в любой месяц.
export type CardWhen = "ledokhod" | "sev" | "mezhen" | "zhatva" | "torg" | "sanny_put" | "zima" | "lyuboy";
export const CARD_WHEN: Record<CardWhen, string> = {
  ledokhod: "ледоход", sev: "сев", mezhen: "межень", zhatva: "жатва", torg: "осенний торг", sanny_put: "санный путь", zima: "зима", lyuboy: "в любой месяц",
};
// Темы колоды акта 1 (koloda.md, раздел 2): первая пачка закрывает восемь из десяти, вторая — «дорогу» и «метки».
// Три раздела второй пачки стоят вне десяти тем: ступени нитей, ходы сил с опорами и соседи по Талице.
export type CardTheme = "zemlya" | "dvory" | "kromka" | "khram" | "dengi" | "doroga" | "lyudi" | "sovet" | "metki" | "predaniya" | "niti" | "sily" | "sosedi";
export const CARD_THEMES: Record<CardTheme, string> = {
  zemlya: "земля и межи", dvory: "дворы — уходят и приходят", kromka: "кромка и зверь", khram: "храм и обряд", dengi: "деньги, подать, долги",
  doroga: "дорога, перевоз, торг", lyudi: "люди и семьи", sovet: "совет и суд", metki: "метки", predaniya: "предания и вести",
  niti: "ступени нитей", sily: "ходы сил и опоры", sosedi: "соседи по Талице",
};
// Сила за карточкой (koloda.md, 7.0, поле «Сила»): чей это ход или кто стоит за карточкой. hod — номер хода силы (src/data/forces.ts, moves),
// opora — id её опоры; «lyubaya» — любая сила (так пишут соглядатаи). text — оговорка словами карточки.
export type ForceId = Force["id"];
export interface CardForce { sila: ForceId | "lyubaya"; hod?: number; opora?: string; text?: string }
// Шкалы сил (forces.ts, scales): расположение и подозрение палаты, напор и вес Ратши. v: +1 — вверх, −1 — вниз.
export type ForceScaleId = "raspolozhenie" | "podozrenie" | "napor" | "ves";
export { SCALE_FORCE };
export interface CardScaleMove { sila: ForceId; scale: ForceScaleId; v: 1 | -1 }

// ---------- разметка под движок (задача И33; svyazi.md, разделы 8–11) ----------
// «Когда» — срок или сезон (8.6): срок — событие привязано к дорожке года и вне её не бывает; сезон — обычно бывает тогда,
// но повод сильнее: нить, ход силы или строка «дальше» зовут карточку в любой месяц.
export type WhenKind = "srok" | "sezon";
export const WHEN_KINDS: Record<WhenKind, string> = {
  srok: "срок: привязано к дорожке года и вне её не бывает", sezon: "сезон: обычно тогда, но повод сильнее",
};
// Толпа — участник без слота: сторона или группа, не человек (8.3, 11.2). Группы — из словаря связей; ещё совет, туллы и марка целиком.
export type Crowd = LinkGroup | "sovet" | "tully" | "marka";
export const CROWDS_EXTRA: Record<Exclude<Crowd, LinkGroup>, string> = { sovet: "совет и помощники", tully: "туллы с того берега", marka: "люди марки без разбора" };
// Кто решает (11.3): слоты карточки; Сенешаль; тот, до кого дошло; тот, кто остался за главного.
export type CardDecider = { kto: "roli"; slots: string[] } | { kto: "seneschal" | "doshlo" | "za_glavnogo" };
// Что стало с работой на месте: сделана, не сделана, наполовину.
export type WorkDone = "da" | "net" | "napolovinu";
// Отложенный исход (10.2): запись с условием и сроком — сборщик проверяет её и, когда условие сошлось, кладёт событие.
// Сюда же идёт исход-развилка: «по случаю», «по натуре человека» — условие названо, следствие остаётся словами карточки.
// esli — условия словаря поводов; srok — срок словами карточки; card и budet — карточка, которая выпадет; pole — что изменится, если ложится в поля.
export interface CardDeferred { esli: Usl[]; srok?: string; text: string; card?: string; budet?: string; pole?: Omit<CardOutcome, "text" | "otlozhen" | "faktura" | "vopros"> }
// Исход словами, который не лёг ни в поля, ни в отложенный исход, ни в фактуру: состояние он меняет, а поля под него нет.
// Вопросы автору — koloda.md, раздел 9: знание Сенешаля, слава места, рост или потеря человека.
export type OutcomeQuestion = "znanie" | "slava" | "chelovek";
export const OUTCOME_QUESTIONS: Record<OutcomeQuestion, string> = {
  znanie: "Сенешаль или решающий узнаёт: «видно, кто…», «улика», «правда может выйти наружу»",
  slava: "слава места или владения: «добрая слава», «здесь строго», «здесь не выдают»",
  chelovek: "человек растёт, уходит или меняется: «помощник вырастет», «марка теряет человека»",
};

// ---------- словарь ролей (svyazi.md, 11.2): слот → род и условие поиска человека ----------
// Шесть родов: где сборщик ищет человека на роль (8.3).
export type RoleRod = "dolzhnost" | "sluzhba" | "sila" | "dvor" | "prishlye" | "cherta";
export const ROLE_RODS: { id: RoleRod; name: string; gde: string }[] = [
  { id: "dolzhnost", name: "должность", gde: "совет и помощники" },
  { id: "sluzhba", name: "служба и мастер при месте", gde: "видные при месте; нет места — нет роли" },
  { id: "sila", name: "человек силы или стороны", gde: "представители сил, соседи, лица лиха; приезжих сборщик приводит" },
  { id: "dvor", name: "двор и родня", gde: "видные и строки дворов — по возрасту и месту в доме" },
  { id: "prishlye", name: "пришлые", gde: "по происхождению («Откуда и чей»); волна пришлых, гости" },
  { id: "cherta", name: "по черте или нити", gde: "у кого есть черта или нить; свидетель — кто был рядом" },
];
// Должности совета Концепта 3 (koncept-3.md, 9.1): два старосты, десятник, ключник, писарь, ловчий; жрец — когда он есть в марке.
export type C3Post = "starosta" | "pisar" | "desyatnik" | "klyuchnik" | "lovchiy" | "zhrets";
export const C3_POSTS: Record<C3Post, string> = { starosta: "староста", pisar: "писарь", desyatnik: "десятник", klyuchnik: "ключник", lovchiy: "ловчий", zhrets: "жрец" };
// Место в доме (naselenie.md, 1.1): по нему ищут человека в строке двора.
export type HouseRole = "glava" | "zhena" | "vdova" | "vdovets" | "syn" | "doch" | "rebyonok" | "starik" | "rabotnik" | "lyuboy" | "dvor";
export const HOUSE_ROLES: Record<HouseRole, string> = {
  glava: "глава двора", zhena: "жена", vdova: "вдова, что держит двор", vdovets: "вдовец", syn: "взрослый сын", doch: "дочь на выданье", rebyonok: "ребёнок",
  starik: "старик", rabotnik: "работник, батрак", lyuboy: "любой взрослый двора", dvor: "двор целиком: глава с семьёй",
};
// Строка словаря. slots — написания слота: пара в двух написаниях — одна строка. Условие поиска — полями по роду и словами (ishchem):
// post и pomoshchnik — должность совета и её помощник; mesto — при каком месте служит; sila и rep — представитель силы (forces.ts);
// storona — человек соседей по Талице; holder — роль «кто держит» из словаря нитей; priezzhiy — приезжий: сборщик приводит его сам (8.2);
// dom — место в доме; origin — происхождения; metka — у человека метка; khozyain — хозяин нити, названной в поводе; mnogo — на слоте несколько человек.
