export const roleWord = (slot: string): RoleWord => {
  const r = ROLE_WORDS.find((x) => x.slots.includes(slot));
  if (!r) throw new Error(`В словаре ролей нет слота ${slot}`);
  return r;
};

// ---------- правила по умолчанию (svyazi.md, 11.3) ----------
// Ясность следа, если карточка её не называет, — по каналу; без канала дело само на виду — «громко».
export const CHANNEL_YASNOST: Record<Channel, Clarity> = {
  ushi: "smutno", molva: "smutno", vid: "zametno", prisutstvie: "zametno", doklad: "zametno", vedomost: "yasno", zhaloba: "yasno", mesto: "yasno",
};
export const traceYasnost = (t: CardTrace, kanal?: Channel): Clarity => t.yasnost ?? (kanal ?? t.gde[0] ? CHANNEL_YASNOST[(kanal ?? t.gde[0])!] : "gromko");
// Кто решает: разметка карточки, а где её нет — стол: Сенешаль. У личного, должностного и пересечения слоты решающих размечены в самой карточке.
export const cardDecider = (c: DeckCard): CardDecider => c.reshaet ?? { kto: "seneschal" };
// Величины словами: «слегка» — шаг, «заметно» — два, «сильно» и «резко» — три.
export const VELICHINY: Record<string, number> = { "слегка": 1, "заметно": 2, "сильно": 3, "резко": 3 };

// ---------- кому вариант по душе ----------
// Метка — полюс признака («poryadok+» — людям порядка), желание или удержка из словаря (src/data/portrait.ts) либо «основа»:
// вложить в долгое, а не в показное (cherty-dannye.md, раздел 9, «Крепкая основа»).
export type CardLike = PoleKey | Want | Hold | "osnova";
// Слова карточек → метки словаря (koloda.md, раздел 6; перевод принят автором 25.11.2026).
export type LikeWord =
  | "обычай" | "порядок" | "выгода" | "покой" | "новое" | "смелость" | "жёсткость" | "гордость" | "вера" | "осторожность" | "щедрость" | "свои" | "прямота"
  | "страх" | "забота" | "мир" | "правда" | "основа" | "смирение" | "мягкость" | "терпение" | "вспыльчивость" | "лукавство" | "любопытство" | "вольность"
  | "сомнение" | "честолюбие" | "близкие" | "место" | "верность";
