// ---------- карточка ----------
// Роль. slot — имя слота, как в завязке: «{староста}»; без слота — участник, которого генератор не подставляет.
// trait, want, thread — условие на роль: черта из мешка, желание, нить и её ступень.
// Разметка (И33): novyy — слот дан разметкой, в карточке роль названа словами; tolpa — участник без слота: сторона или группа;
// k — участник без слота уточняет уже названную роль (или называет, кем ещё её можно занять); bias — пристрастие доклада у роли.
export interface CardRole {
  slot?: string; text?: string; trait?: string; want?: Want; thread?: { nit: ThreadId; step?: string; vetv?: string; spit?: true };
  novyy?: true; tolpa?: Crowd; k?: string[]; bias?: string;
}
// Исход варианта. text — исход словами карточки; пусто, если карточка исхода не называет. Серебро — в условных единицах: −1 — трата, −2 — большая трата, +1 — приход (сколько это монет, покажут прогоны с движком).
// Хлеб и сено — словами. Дворы — сколько пришло или ушло. Слово Сенешаля: +1 — крепнет, −1 — слабеет, «zalog» — дано под залог.
// Отношения: кто (слот в скобках или группа словами) и в какую сторону. Лихо: +1 — растёт, −1 — падает (likho.md, раздел 3).
// Вторая пачка: shkala — шкалы сил словом; doverie — доверие соседей по Талице (sily.md, 16), doverieDo — до какой ступени;
// tyagota — вариант против души Сенешаля (koncept-3.md, 13.2); zhetonHod — что стало с жетоном, который уже лежит на дорожке;
// podChuzhoyRukoy — акт идёт дальше «под чужой рукой» по уговору (118, отступное).
export interface CardOutcome {
  text: string;
  serebro?: number;
  khleb?: string;
  seno?: string;
  dvory?: number;
  slovo?: 1 | -1 | "zalog";
  otnosheniya?: { kto: string; v: 1 | -1 }[];
  likho?: 1 | -1;
  nit?: { nit: ThreadId; step?: string; kak?: "spit" | "stoit" | "vniz" }; // вариант открывает или двигает нить; kak — нить засыпает, стоит или шагает вниз
  trait?: string;                          // вариант даёт черту из мешка
  delo?: DealId;                           // вариант — отдельное дело Сенешаля
  zheton?: string;                         // жетон обязательства на дорожке года
  zhetonHod?: { zheton: string; chto: "sorvan" | "sdvinut" | "ugroza" | "tsel" }; // жетон сорван, сдвинут, под угрозой, цел
  shkala?: CardScaleMove[];
  doverie?: 1 | -1;
  doverieDo?: string;
  tyagota?: true;
  podChuzhoyRukoy?: true;
  // Разметка исходов словами (И33; svyazi.md, 10.2). Новые поля: ступень места; укрытие деревни; руки заняты до срока; работа сделана или нет.
  mesto?: { mesto: DeckPlace; v: 1 | -1 };
  ukrytie?: { derevnya: "nizhnyaya" | "verkhnyaya" | "derevnya" | "zamok"; v: 1 | -1 };
  ruki?: { kto: string; do?: string };
  rabota?: { chto: string; sdelana: WorkDone };
  otlozhen?: CardDeferred[];   // отложенный исход и исход-развилка
  faktura?: true;              // исход остаётся строкой летописи, состояния не меняет
  vopros?: OutcomeQuestion;    // исход меняет состояние, а поля под него нет — вопрос автору
}
// Вариант. words — слова карточки «кому по душе», likes — они же метками словаря (собирает v()).
// derzhit — какие удержки против варианта (svyazi.md, 9.2): совесть — по умолчанию у вариантов «по душе лукавым»; страх — за вариант можно ответить;
// верность — вариант за спиной Сенешаля или против его слова; «правило» в карточку не пишется: движок сверяет вариант с рамкой игрока.
// razgovor — вариант Сенешаля, где он говорит с человеком (9.4): слот собеседника; выбрав вариант, игрок выбирает подход.
export interface CardVariant { text: string; words: LikeWord[]; likes: CardLike[]; outcome: CardOutcome; derzhit?: Exclude<Hold, "pravilo">[]; razgovor?: string }
// След: канал из словаря (CHANNELS) и текст. Каналов несколько — видно по любому из них; без канала — карточка его не называет: дело само на виду.
// yasnost — ясность следа, если карточка её называет; note — оговорка из скобок: «если сводили свои», «в замке», «палаты».
// poTekstu — канал дан разметкой по тексту строки: карточка его не называет (11.3); zametka — строка не след, а оговорка карточки.
export interface CardTrace { gde: Channel[]; text: string; yasnost?: Clarity; note?: string; poTekstu?: true; zametka?: true }
// Дальше: на карточку колоды (card), на нить словаря (nit) и её ступень (step) или на карточку, которой ещё нет (budet — её название).
// zametka — строка «дальше» словами остаётся заметкой: ни карточки, ни нити за ней нет (10.3).
export interface CardNext { text: string; card?: string; nit?: ThreadId; step?: string; budet?: string; zametka?: true }
// Исход опоры: написан вручную; kogda — когда он выпадает.
export interface AnchorOutcome { name: string; kogda?: string; text?: string }
export interface DeckCard {
  n: number;                 // номер в koloda.md
  id: string;
  name: string;
  theme: CardTheme;
  level?: CardLevel;         // у предания уровня нет: решает тот, до кого дошла молва
  rises?: CardLevel | "molva"; // «→»: куда карточка поднимается; у предания — уходит в молву
  kind: CardKind;
  delo?: DealId;             // у эпизода — какого дела
  tags?: ("sled" | "beda" | "likho")[]; // likho — карточка лиха (likho.md, раздел 10)
  // ступень или начало нити; esli — при каком условии; ili — «или» вторая нить; vetv — ветвь нити
  thread?: { nit: ThreadId; step?: string; start?: boolean; esli?: string; ili?: ThreadId; vetv?: string };
  sila?: CardForce;          // чей ход или кто стоит за карточкой
  hod?: { open: boolean; openNote?: string; otkrytaya?: string }; // у хода силы: открытый или скрытый; otkrytaya — карточка с открытой стороной хода
  opora?: { chtoSmotrit?: string; vybor?: string; ishody: AnchorOutcome[]; dosrochno?: string; gdeSeneschal?: string }; // у опоры
  where: CardWhere[];
  outside?: Outside;         // место за пределами владения
  whereNote?: string;        // как место названо в карточке
  when: CardWhen;
  kogda?: WhenKind;          // срок или сезон — у карточки с «когда»; «в любой месяц» — без пометы
  whenNote?: string;
  who: CardRole[];
  usl: Usl[];                // повод условиями словаря (src/data/conditions.ts): нужны все; пусто — «время, место и роли»
  oneOf?: { slots: string[]; trait: string }; // черта — у одного из этих слотов
  povod?: string;
  chtoDelaet?: string;       // у скрытого хода и опоры — что делает сила
  byotPo?: string;           // у хода — по чему бьёт
  intro?: string;            // завязки нет у скрытого хода и опоры: игрок встречает только следы
  decides?: string;          // чьи это варианты, если не того, кому карточка выпала по уровню
  reshaet?: CardDecider;     // кто решает, разметкой; нет — по уровню (cardDecider)
  variants: CardVariant[];   // пусто у скрытого хода, опоры и хода с открытой стороной в другой карточке
  ispolnenie?: string;       // у хода — как он ложится на натуру исполнителя
  traces: CardTrace[];
  shkaly?: string[];         // у хода и опоры — как ход и ответ двигают шкалы, словами карточки
  vyshe?: string;
  vysheUsl?: Cond[];         // «выше» условиями словаря: хватает любого
  dalshe: CardNext[];
  // po — на что карточка опирается кроме текстов мира: документ замысла, справочник края
  source: { how: "kak_est" | "perenos" | "po_zamyslu"; from?: string; texts: number[]; po?: string };
}

const likesOf = (words: LikeWord[]): CardLike[] => [...new Set(words.flatMap((x) => LIKE_WORDS.find((q) => q.word === x)!.likes))];
// Вариант: текст, слова «кому по душе», исход словами и его поля.
// Удержки против варианта: совесть — по умолчанию у вариантов «по душе лукавым» (svyazi.md, 9.2), остальное — разметкой.
type VariantExtra = Pick<CardVariant, "derzhit" | "razgovor">;
const derzhitOf = (words: LikeWord[], extra: VariantExtra): VariantExtra => {
  const list = [...new Set([...(words.includes("лукавство") ? ["sovest" as const] : []), ...(extra.derzhit ?? [])])];
  return { ...(list.length ? { derzhit: list } : {}), ...(extra.razgovor ? { razgovor: extra.razgovor } : {}) };
};
// Вариант: текст, слова «кому по душе», исход словами и его поля; последним — что держит и с кем разговор.
const v = (text: string, words: LikeWord[], outcome: string, fields: Omit<CardOutcome, "text"> = {}, extra: VariantExtra = {}): CardVariant => ({
  text, words, likes: likesOf(words), outcome: { text: outcome, ...fields }, ...derzhitOf(words, extra),
});
const slot = (name: string, extra: Omit<CardRole, "slot"> = {}): CardRole => ({ slot: name, ...extra });
// Участник без слота — одно из трёх (svyazi.md, 11.2): толпа, уточнение к названной роли или роль, получившая слот разметкой.
const tolpa = (text: string, gruppa: Crowd): CardRole => ({ text, tolpa: gruppa });
const utoch = (text: string, ...k: string[]): CardRole => ({ text, k });
const rol = (name: string, text: string, extra: Omit<CardRole, "slot" | "text" | "novyy"> = {}): CardRole => ({ slot: name, text, novyy: true, ...extra });
const roli = (...slots: string[]): CardDecider => ({ kto: "roli", slots });
const DOSHLO: CardDecider = { kto: "doshlo" };
const SENESCHAL: CardDecider = { kto: "seneschal" };
const ZA_GLAVNOGO: CardDecider = { kto: "za_glavnogo" };
const tr = (gde: Channel | Channel[], text: string, extra: Omit<CardTrace, "gde" | "text"> = {}): CardTrace => ({ gde: Array.isArray(gde) ? gde : [gde], text, ...extra });
const asIs = (...texts: number[]): DeckCard["source"] => ({ how: "kak_est", texts });
const moved = (from: string, ...texts: number[]): DeckCard["source"] => ({ how: "perenos", from, texts });
const byDoc = (po: string, ...texts: number[]): DeckCard["source"] => ({ how: "po_zamyslu", texts, po });
const shk = (scale: ForceScaleId, v: 1 | -1): CardScaleMove => ({ sila: SCALE_FORCE[scale], scale, v });
const up = (kto: string): { kto: string; v: 1 } => ({ kto, v: 1 });
